      $this->alterFormValues($form_state);
      $source = $this->sourceManager->getSource($this->data['node_id'], [], $this->data, $contexts);

      if ($source instanceof SourceWithSlotsInterface) {
        $form = $source->settingsFormPropsOnly([], $form_state);
