      // self::writeDefault().
      if ($operation === 'view') {
        $result = AccessResult::allowedIf($node->isPublished());
        if (!$node->isNew()) {
          $result->addCacheableDependency($node);
        }

        return $result;
      }

      return AccessResult::neutral();
